import React, { useState } from 'react';

interface ControlValues {
    outer: boolean;
    onlySuggestions: boolean;
    success: boolean;
    warning: boolean;
}

const Controls: React.FC<{ onChange: (values: ControlValues) => void }> = ({ onChange }) => {
    const [values, setValues] = useState<ControlValues>({
        outer: false,
        onlySuggestions: false,
        success: false,
        warning: false
    });

    const handleChange = (key: keyof ControlValues, value: boolean) => {
        const newValues = { ...values, [key]: value };
        setValues(newValues);
        onChange(newValues);
    };

    return (
        <div>
            <label>
                <input
                    type="checkbox"
                    checked={values.outer}
                    onChange={(e) => handleChange('outer', e.target.checked)}
                />
                Outer?
            </label>
            <label>
                <input
                    type="checkbox"
                    checked={values.onlySuggestions}
                    onChange={(e) => handleChange('onlySuggestions', e.target.checked)}
                />
                OnlySuggestions?
            </label>
            <label>
                <input
                    type="checkbox"
                    checked={values.success}
                    onChange={(e) => handleChange('success', e.target.checked)}
                />
                Success?
            </label>
            <label>
                <input
                    type="checkbox"
                    checked={values.warning}
                    onChange={(e) => handleChange('warning', e.target.checked)}
                />
                Warning?
            </label>
        </div>
    );
};

export default Controls;
